function minJumps(arr) {
  const n = arr.length;
  const sameValue = new Map();
  for (let i = 0; i < n; i++) {
    if (!sameValue.has(arr[i])) sameValue.set(arr[i], []);
    sameValue.get(arr[i]).push(i);
  }
  const visited = new Array(n).fill(false);
  visited[0] = true;
  let queue = [0];
  let steps = 0;
  while (queue.length > 0) {
    const next = [];
    for (const i of queue) {
      if (i === n - 1) return steps;
      const targets = [i - 1, i + 1, ...(sameValue.get(arr[i]) ?? [])];
      sameValue.delete(arr[i]);
      for (const j of targets) {
        if (j >= 0 && j < n && !visited[j]) {
          visited[j] = true;
          next.push(j);
        }
      }
    }
    queue = next;
    steps++;
  }
  return -1;
}

