function minJumps(arr) {
  // Relax every allowed move until no distance improves (Bellman-Ford style).
  const n = arr.length;
  const dist = new Array(n).fill(Infinity);
  dist[0] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let a = 0; a < n; a++) {
      for (let b = 0; b < n; b++) {
        const allowed = a !== b && (Math.abs(a - b) === 1 || arr[a] === arr[b]);
        if (allowed && dist[a] + 1 < dist[b]) {
          dist[b] = dist[a] + 1;
          changed = true;
        }
      }
    }
  }
  return dist[n - 1];
}

