function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(1500, 2000) : int(1, 12);
  const mode = rand();
  let arr;
  if (mode < 0.15) {
    // All values distinct: only neighbour steps help.
    const base = int(-100000000, 100000000 - n);
    arr = Array.from({ length: n }, (_, i) => base + i);
  } else if (mode < 0.3) {
    // One value almost everywhere: the naive search revisits it over and over.
    const common = int(-100000000, 100000000);
    arr = Array.from({ length: n }, () => (rand() < 0.95 ? common : int(-100000000, 100000000)));
  } else if (mode < 0.55) {
    // Few distinct values: many long jumps, short answers.
    const k = int(2, large ? 20 : 4);
    arr = Array.from({ length: n }, () => int(1 - k, k - 1));
  } else {
    // Many distinct values with sparse repeats: answers of moderate length.
    const k = large ? int(n / 2, 2 * n) : int(3, 10);
    const spread = rand() < 0.3 ? Math.floor(100000000 / k) : 1;
    arr = Array.from({ length: n }, () => (int(0, k - 1) - Math.floor(k / 2)) * spread);
  }
  return [arr];
}
